/// <summary>
/// The <c>METFinancialDimensionHelper</c> class is a class used to perform charge through financial dimension operations
/// </summary>
public class METFinancialDimensionHelper
{
}

Method.Source:
    /// <summary>
    /// Performs a lookup on the <c>DimensionAttribute</c> table.
    /// </summary>
    /// <param name="_lookupCtrl">
    /// The <c>FormStringControl</c> control that the lookup will be attached to.
    /// </param>
    public static void lookupProfitCentre(FormStringControl   _lookupCtrl)
    {
        FormStringControl   ctrl = _lookupCtrl as FormStringControl;
        Args                args;
        FormRun             formRun;
        DimensionAttribute  dimensionAttribute;
        #define.ProfitCentre("@MET:CBCTProfitCentre")

        select dimensionAttribute where dimensionAttribute.Name == #ProfitCentre;

        args = new Args();
        args.record(dimensionAttribute);
        args.caller(_lookupCtrl);
        args.name(formstr(DimensionLookup));
        formRun = classfactory.formRunClass(args);
        formRun.init();
        ctrl.performFormLookup(formRun);
    }
